class Solution
{
public:
    vector<string> generatePossibleNextMoves(string currentState) {
        vector<string> result;
        for (int i = 0; i + 1 < (int)currentState.size(); ++i)
        {
            if (currentState[i] == '+' && currentState[i + 1] == '+')
            {
                string next = currentState;
                next[i] = '-';
                next[i + 1] = '-';
                result.push_back(next);
            }
        }
        return result;
    }
};
